#[test]
fn fetch_events_succeeds_and_returns_only_matching_later_events() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let events = vec![
        event(et.clone(), 1),
        event(et.clone(), 2),
        event(other_event_type(), 3), // different EventType - excluded
        event(et.clone(), 4),
    ];

    let result = event_store::fetch_events(&t, &events, &[], Some(1), None).unwrap();

    assert_eq!(
        result.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![2, 4]
    );
}

#[test]
fn fetch_events_with_no_after_sequence_starts_from_the_beginning() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let events = vec![event(et.clone(), 0), event(et.clone(), 1)];

    let result = event_store::fetch_events(&t, &events, &[], None, None).unwrap();

    assert_eq!(
        result.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![0, 1]
    );
}

/// rule-failure.FetchEvents.1 - `requires: token.status = active`.
#[test]
fn fetch_events_rejects_a_revoked_token() {
    let t = token(TokenStatus::Revoked, event_type(true));

    let err = event_store::fetch_events(&t, &[], &[], None, None).unwrap_err();

    assert_eq!(err.code(), access_control::Error::TokenNotActive.code());
}

/// rule-failure.FetchEvents.2 - `requires: token.event_type = read_type`.
/// Structurally unreachable rather than runtime-tested: `fetch_events`
/// doesn't accept `read_type` as a separate parameter, it derives it from
/// `token.event_type` (see the doc comment on `fetch_events`), so there is
/// no call shape that can violate this - it's true by construction, the
/// same way a type system rules out an illegal state rather than
/// rejecting it at runtime.
#[test]
fn fetch_events_read_type_is_always_the_tokens_event_type_by_construction() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    // No `read_type` argument exists to disagree with `t.event_type` -
    // this test exists to document the obligation, not exercise a branch.
    let _ = event_store::fetch_events(&t, &[], &[], None, None);
    assert_eq!(t.event_type, et);
}

/// rule-failure.FetchEvents.3 - `requires: read_type.event_read_allowed = true`.
#[test]
fn fetch_events_rejects_an_event_type_not_opted_into_reads() {
    let t = token(TokenStatus::Active, event_type(false));

    let err = event_store::fetch_events(&t, &[], &[], None, None).unwrap_err();

    assert_eq!(err.code(), event_store::Error::EventReadNotAllowed.code());
}

/// rule-failure.FetchEvents.4 - `requires: valid_filters(read_type, filters)`.
#[test]
fn fetch_events_rejects_an_invalid_filter() {
    let t = token(TokenStatus::Active, event_type(true));
    // event_type()'s schema is "{}" - "amount" names no field it declares.
    let bogus_filter = vec![Filter {
        field: "amount".into(),
        operator: FilterOperator::GreaterThan,
        value: "10".into(),
    }];

    let err = event_store::fetch_events(&t, &[], &bogus_filter, None, None).unwrap_err();

    assert_eq!(err.code(), event_store::Error::InvalidFilter.code());
}

// ---------------------------------------------------------------------
// rule-success.ConsumeEvents / rule-failure.ConsumeEvents.{1..5}
// ---------------------------------------------------------------------

#[test]
fn consume_events_provisions_a_cursor_on_first_use() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let events = vec![event(et.clone(), 0), event(et.clone(), 1)];

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        None,
        Some(AckMode::AutoAdvance),
        &events,
        &[],
        timestamp(100),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![0, 1]
    );
    match cursor_update {
        CursorUpdate::Created(cursor) => {
            assert_eq!(cursor.token, t);
            assert_eq!(cursor.ack_mode, AckMode::AutoAdvance);
            assert_eq!(cursor.sequence, 1); // highest served
            assert_eq!(cursor.updated_at, timestamp(100));
            // Codeberg issue #25 (docs/architecture.md §53) -
            // auto_advance never claims: it has no equivalent gap to
            // close (see `ReadCursor.checked_out_at`'s own spec doc
            // comment).
            assert_eq!(cursor.checked_out_at, None);
        }
        other => panic!("expected ReadCursor.created, got {other:?}"),
    }
}

/// `at_sequence`'s whole point over `latest`: the token's first call can
/// replay *some* history from a caller-chosen cutoff, not just none at
/// all - here sequence 0 stays unserved (at or before the cutoff) while
/// 1 and 2, already historical relative to this call, are served
/// alongside nothing-new-yet.
#[test]
fn consume_events_at_sequence_starts_strictly_after_the_given_sequence() {
    let et = event_type(true);
    let t = EventReadToken {
        start_from: EventReadStartPosition::AtSequence,
        start_at_sequence: Some(0),
        ..token(TokenStatus::Active, et.clone())
    };
    let events = vec![event(et.clone(), 0), event(et.clone(), 1), event(et, 2)];

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        None,
        Some(AckMode::AutoAdvance),
        &events,
        &[],
        timestamp(100),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![1, 2]
    );
    match cursor_update {
        CursorUpdate::Created(cursor) => assert_eq!(cursor.sequence, 2),
        other => panic!("expected ReadCursor.created, got {other:?}"),
    }
}

/// `at_time`'s own version of the same proof: the cutoff sits strictly
/// between two events' own `created_at`, so the earlier one is excluded
/// and the later one - already historical relative to this call - is
/// served, exactly the "replay from a chosen point in time" behaviour
/// `at_sequence` gives by number instead.
#[test]
fn consume_events_at_time_starts_strictly_after_events_at_or_before_that_cutoff() {
    let et = event_type(true);
    let cutoff = timestamp(50);
    let t = EventReadToken {
        start_from: EventReadStartPosition::AtTime,
        start_at_time: Some(cutoff),
        ..token(TokenStatus::Active, et.clone())
    };
    let events = vec![
        event_at(et.clone(), 0, timestamp(10)), // before the cutoff - excluded
        event_at(et.clone(), 1, timestamp(50)), // exactly at the cutoff - excluded
        event_at(et.clone(), 2, timestamp(90)), // after the cutoff - served
    ];

    let ConsumeEventsResult { served, .. } = event_store::consume_events(
        &t,
        None,
        Some(AckMode::AutoAdvance),
        &events,
        &[],
        timestamp(100),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![2]
    );
}

/// A `start_at_time` with nothing committed at or before it behaves
/// exactly as `beginning` would - the spec's own "empty means the token
/// gets the whole stream" note on `at_time_position`.
#[test]
fn consume_events_at_time_with_no_events_before_the_cutoff_serves_everything() {
    let et = event_type(true);
    let t = EventReadToken {
        start_from: EventReadStartPosition::AtTime,
        start_at_time: Some(timestamp(5)),
        ..token(TokenStatus::Active, et.clone())
    };
    let events = vec![
        event_at(et.clone(), 0, timestamp(50)),
        event_at(et, 1, timestamp(60)),
    ];

    let ConsumeEventsResult { served, .. } = event_store::consume_events(
        &t,
        None,
        Some(AckMode::AutoAdvance),
        &events,
        &[],
        timestamp(100),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![0, 1]
    );
}

#[test]
fn consume_events_auto_advance_moves_the_cursor_to_the_highest_served_sequence() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let existing = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::AutoAdvance,
        sequence: 5,
        updated_at: timestamp(0),
        checked_out_at: None,
    };
    let events = vec![event(et.clone(), 6), event(et.clone(), 7)];

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        Some(&existing),
        None,
        &events,
        &[],
        timestamp(200),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![6, 7]
    );
    assert_eq!(
        cursor_update,
        CursorUpdate::Advanced {
            sequence: 7,
            updated_at: timestamp(200)
        }
    );
}

/// `sequence`/`position` never moves on serve, in either mode - but
/// unlike before Codeberg issue #25's investigation (docs/architecture.md
/// §53), a `manual_ack` cursor with no live claim now *does* get one:
/// `Claimed`, not `Unchanged`. See
/// `consume_events_manual_ack_with_a_live_claim_serves_nothing` below for
/// the case this test used to conflate with "nothing happens" - a second
/// call while a claim is still live really is `Unchanged`.
#[test]
fn consume_events_manual_ack_never_moves_the_cursor_on_serve() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let existing = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 5,
        updated_at: timestamp(0),
        checked_out_at: None,
    };
    let events = vec![event(et.clone(), 6)];

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        Some(&existing),
        None,
        &events,
        &[],
        timestamp(200),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![6]
    );
    assert_eq!(
        cursor_update,
        CursorUpdate::Claimed {
            checked_out_at: timestamp(200)
        }
    );
}

/// Codeberg issue #25's investigation (docs/architecture.md §53) - the
/// gap this closes: a second caller racing a still-live claim on the
/// same token must be served nothing, not the identical unacknowledged
/// batch a first caller may still be acting on externally.
#[test]
fn consume_events_manual_ack_with_a_live_claim_serves_nothing() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let existing = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 5,
        updated_at: timestamp(0),
        // Claimed one minute ago - well inside the five-minute
        // checkout_lease() fixture, so still live.
        checked_out_at: Some(timestamp(150)),
    };
    let events = vec![event(et, 6)];

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        Some(&existing),
        None,
        &events,
        &[],
        timestamp(200),
        checkout_lease(),
    )
    .unwrap();

    assert!(
        served.is_empty(),
        "a second caller must not be served the same unacknowledged batch"
    );
    assert_eq!(cursor_update, CursorUpdate::Unchanged);
}

/// Codeberg issue #25's investigation - the other half of the same
/// guarantee: a claim older than `checkout_lease` is abandoned, not
/// live, so this call succeeds exactly as if nothing had claimed it -
/// serving the batch and reclaiming the cursor with a fresh
/// `checked_out_at`, the self-healing path for a caller that was served
/// but crashed before acknowledging.
#[test]
fn consume_events_manual_ack_reclaims_a_stale_claim() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let existing = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 5,
        updated_at: timestamp(0),
        // Six minutes before `now` below - past the five-minute
        // checkout_lease() fixture, so stale.
        checked_out_at: Some(timestamp(200 - 6 * 60)),
    };
    let events = vec![event(et, 6)];

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        Some(&existing),
        None,
        &events,
        &[],
        timestamp(200),
        checkout_lease(),
    )
    .unwrap();

    assert_eq!(
        served.iter().map(|e| e.sequence).collect::<Vec<_>>(),
        vec![6],
        "a stale claim must be reclaimed, not treated as still live"
    );
    assert_eq!(
        cursor_update,
        CursorUpdate::Claimed {
            checked_out_at: timestamp(200)
        }
    );
}

/// Codeberg issue #25's investigation - the `manual_ack` twin of
/// `consume_events_provisions_a_cursor_on_first_use`: a brand new
/// cursor's very first serve claims it too, unlike `auto_advance`, which
/// never sets `checked_out_at` at all (that test's own assertion).
#[test]
fn consume_events_manual_ack_provisions_a_claimed_cursor_on_first_use() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let events = vec![event(et, 0)];

    let ConsumeEventsResult { cursor_update, .. } = event_store::consume_events(
        &t,
        None,
        Some(AckMode::ManualAck),
        &events,
        &[],
        timestamp(100),
        checkout_lease(),
    )
    .unwrap();

    match cursor_update {
        CursorUpdate::Created(cursor) => {
            assert_eq!(cursor.ack_mode, AckMode::ManualAck);
            assert_eq!(cursor.checked_out_at, Some(timestamp(100)));
        }
        other => panic!("expected ReadCursor.created, got {other:?}"),
    }
}

/// Per the spec's `ensures` block, the `auto_advance` branch writes
/// `cursor.sequence = next_position` unconditionally, even when nothing
/// new matched and `next_position` falls back to the unchanged `position`
/// (`highest_sequence(served) ?? position`) - so this is still
/// `Advanced`, at the same sequence, not `Unchanged`. `Unchanged` is only
/// reachable for `manual_ack` with a still-live claim (Codeberg issue
/// #25's investigation narrowed this - see
/// `consume_events_manual_ack_with_a_live_claim_serves_nothing` below).
#[test]
fn consume_events_auto_advance_with_nothing_new_still_reports_advanced_at_the_same_sequence() {
    let et = event_type(true);
    let t = token(TokenStatus::Active, et.clone());
    let existing = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::AutoAdvance,
        sequence: 5,
        updated_at: timestamp(0),
        checked_out_at: None,
    };

    let ConsumeEventsResult {
        served,
        cursor_update,
    } = event_store::consume_events(
        &t,
        Some(&existing),
        None,
        &[],
        &[],
        timestamp(200),
        checkout_lease(),
    )
    .unwrap();

    assert!(served.is_empty());
    assert_eq!(
        cursor_update,
        CursorUpdate::Advanced {
            sequence: 5,
            updated_at: timestamp(200)
        }
    );
}

