// ---------------------------------------------------------------------
// rule-success.AcknowledgeEvents / rule-failure.AcknowledgeEvents.{1..4}
// ---------------------------------------------------------------------

#[test]
fn acknowledge_events_moves_the_cursor_forward() {
    let t = token(TokenStatus::Active, event_type(true));
    let cursor = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 5,
        updated_at: timestamp(0),
        checked_out_at: None,
    };

    let (sequence, updated_at) =
        event_store::acknowledge_events(&t, Some(&cursor), 9, timestamp(300)).unwrap();

    assert_eq!(sequence, 9);
    assert_eq!(updated_at, timestamp(300));
}

#[test]
fn acknowledge_events_allows_reconfirming_ground_already_covered() {
    let t = token(TokenStatus::Active, event_type(true));
    let cursor = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 5,
        updated_at: timestamp(0),
        checked_out_at: None,
    };

    let (sequence, _) =
        event_store::acknowledge_events(&t, Some(&cursor), 5, timestamp(300)).unwrap();

    assert_eq!(sequence, 5);
}

/// rule-failure.AcknowledgeEvents.1 - `requires: token.status = active`.
#[test]
fn acknowledge_events_rejects_a_revoked_token() {
    let t = token(TokenStatus::Revoked, event_type(true));
    let cursor = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 0,
        updated_at: timestamp(0),
        checked_out_at: None,
    };

    let err = event_store::acknowledge_events(&t, Some(&cursor), 0, timestamp(0)).unwrap_err();

    assert_eq!(err.code(), access_control::Error::TokenNotActive.code());
}

/// rule-failure.AcknowledgeEvents.2 - `requires: exists cursor`.
#[test]
fn acknowledge_events_rejects_a_token_with_no_cursor_yet() {
    let t = token(TokenStatus::Active, event_type(true));

    let err = event_store::acknowledge_events(&t, None, 0, timestamp(0)).unwrap_err();

    assert_eq!(err.code(), event_store::Error::NoReadCursor.code());
}

/// rule-failure.AcknowledgeEvents.3 - `requires: cursor.ack_mode = manual_ack`.
#[test]
fn acknowledge_events_rejects_an_auto_advance_cursor() {
    let t = token(TokenStatus::Active, event_type(true));
    let cursor = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::AutoAdvance,
        sequence: 0,
        updated_at: timestamp(0),
        checked_out_at: None,
    };

    let err = event_store::acknowledge_events(&t, Some(&cursor), 0, timestamp(0)).unwrap_err();

    assert_eq!(err.code(), event_store::Error::NotManualAckCursor.code());
}

/// rule-failure.AcknowledgeEvents.4 - `requires: sequence >= cursor.sequence`.
#[test]
fn acknowledge_events_rejects_moving_the_cursor_backwards() {
    let t = token(TokenStatus::Active, event_type(true));
    let cursor = ReadCursor {
        token: t.clone(),
        ack_mode: AckMode::ManualAck,
        sequence: 5,
        updated_at: timestamp(0),
        checked_out_at: None,
    };

    let err = event_store::acknowledge_events(&t, Some(&cursor), 4, timestamp(0)).unwrap_err();

    assert_eq!(
        err.code(),
        event_store::Error::AcknowledgementRegresses.code()
    );
}

// ---------------------------------------------------------------------
// invariant.UniqueReadCursorPerToken
// ---------------------------------------------------------------------
//
// "At most one cursor per EventReadToken" is enforced by keying the
// (eventual sqlx-backed) cursor store by the token alone - the same
// UNIQUE-constraint pattern docs/architecture.md uses throughout. This
// property test simulates that store with a `HashMap<TokenId,
// ReadCursor>` and drives it through `consume_events` for randomly
// interleaved tokens, checking the map never needs a second entry for a
// token that already has one - i.e. the get-or-create call in
// `consume_events` is idempotent per token, which is what makes the
// invariant hold once a real store enforces the key.

fn token_id(t: &EventReadToken) -> (String, String) {
    (
        t.event_type.bounded_context.name.clone(),
        t.event_type.name.clone(),
    )
}

proptest! {
    #[test]
    fn unique_read_cursor_per_token_holds_across_interleaved_consumes(
        token_indices in prop::collection::vec(0..3usize, 1..30),
    ) {
        let tokens = [
            token(TokenStatus::Active, event_type(true)),
            token(TokenStatus::Active, other_event_type()),
            token(
                TokenStatus::Active,
                EventType {
                    bounded_context: bounded_context("billing"),
                    name: "InvoiceIssued".into(),
                    ..event_type(true)
                },
            ),
        ];
        let mut cursors: std::collections::HashMap<(String, String), ReadCursor> = std::collections::HashMap::new();

        for idx in token_indices {
            let t = &tokens[idx];
            let key = token_id(t);
            let existing = cursors.get(&key);
            let ack_mode = if existing.is_none() { Some(AckMode::AutoAdvance) } else { None };

            let result = event_store::consume_events(
                t,
                existing,
                ack_mode,
                &[],
                &[],
                Utc::now(),
                checkout_lease(),
            )
            .unwrap();
            if let CursorUpdate::Created(cursor) = result.cursor_update {
                let previous = cursors.insert(key.clone(), *cursor);
                prop_assert!(previous.is_none(), "a second ReadCursor.created for a token that already has one");
            }
        }

        // At most one entry per distinct token, by construction of the map key.
        prop_assert!(cursors.len() <= tokens.len());
    }
}

